begin;
-- Reviewable schema draft. Apply only to a separately approved development database.
create schema tib_sweep_private;
revoke all on schema tib_sweep_private from public,anon;
grant usage on schema tib_sweep_private to authenticated;
create table tib_sweep_private.bank(chapter integer primary key check(chapter between 1 and 47), questions jsonb not null);
create table tib_sweep_private.progress(user_id uuid primary key references auth.users(id), mode text not null default 'guided' check(mode in ('guided','self-study')), passed integer[] not null default '{}', updated_at timestamptz not null default now());
create table tib_sweep_private.attempts(id bigint generated always as identity primary key,user_id uuid not null references auth.users(id),chapter integer not null check(chapter between 0 and 47),kind text not null,payload jsonb not null,score numeric,version text not null default '20261013-v1',created_at timestamptz not null default now());
create index on tib_sweep_private.attempts(user_id,created_at);
alter table tib_sweep_private.bank enable row level security;
alter table tib_sweep_private.progress enable row level security;
alter table tib_sweep_private.attempts enable row level security;
revoke all on all tables in schema tib_sweep_private from public,anon,authenticated;
create policy owner_read_progress on tib_sweep_private.progress for select to authenticated using(user_id=(select auth.uid()));
create policy owner_read_attempts on tib_sweep_private.attempts for select to authenticated using(user_id=(select auth.uid()));
-- Narrow privileged operation: keys and score writes must be inaccessible to clients.
create function tib_sweep_private.assessment(action text,chapter integer,payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); p tib_sweep_private.progress; qs jsonb; earned integer:=0; total integer; score numeric; feedback jsonb:='[]'; item jsonb; i integer:=0;
begin
 if uid is null or not exists(select 1 from public.enrollments e where e.user_id=uid and e.course='TIB-FULL-SWEEP' and e.is_active and (e.start_date is null or e.start_date<=current_date) and (e.expiry_date is null or e.expiry_date>=current_date)) then raise exception 'Active course enrollment required' using errcode='42501';end if;
 insert into tib_sweep_private.progress(user_id) values(uid) on conflict do nothing;
 select * into p from tib_sweep_private.progress where user_id=uid for update;
 if action='state' then return jsonb_build_object('mode',p.mode,'passed',p.passed,'version','20261013-v1');end if;
 if action='mode' then
  if payload->>'mode' not in ('guided','self-study') or payload->>'mode' is null then raise exception 'Invalid mode';end if;
  update tib_sweep_private.progress set mode=payload->>'mode',updated_at=now() where user_id=uid returning * into p;
  insert into tib_sweep_private.attempts(user_id,chapter,kind,payload) values(uid,0,'mode',payload);
  return jsonb_build_object('mode',p.mode,'passed',p.passed);
 end if;
 if chapter is null or chapter not between 1 and 47 then raise exception 'Invalid chapter';end if;
 if p.mode='guided' and exists(select 1 from generate_series(1,chapter-1) c where not c=any(p.passed)) then raise exception 'Earlier chapter locked' using errcode='42501';end if;
 if action='practice' then
  if jsonb_typeof(payload->'responses') is distinct from 'array' or jsonb_array_length(payload->'responses')<>5 or length(payload::text)>30000 then raise exception 'Five bounded responses required';end if;
  insert into tib_sweep_private.attempts(user_id,chapter,kind,payload) values(uid,chapter,'unscored-interview',payload);
  select questions into qs from tib_sweep_private.bank b where b.chapter=assessment.chapter;
  return jsonb_build_object('saved',true,'scored',false,'anchors',(select jsonb_agg(jsonb_build_object('prompt',q->'prompt','anchor',q->'anchor')) from jsonb_array_elements(qs) q));
 end if;
 if action<>'submit' then raise exception 'Invalid action';end if;
 select questions into qs from tib_sweep_private.bank b where b.chapter=assessment.chapter;
 if qs is null then raise exception 'Question bank unavailable';end if; total:=jsonb_array_length(qs);
 if jsonb_typeof(payload->'answers') is distinct from 'array' or jsonb_array_length(payload->'answers')<>total then raise exception 'All answers required';end if;
 for item in select * from jsonb_array_elements(qs) loop
  if (payload->'answers'->i)::text not in ('0','1','2','3') then raise exception 'Invalid answer';end if;
  if payload->'answers'->i=item->'answer' then earned:=earned+1;end if;
  feedback:=feedback||jsonb_build_array(jsonb_build_object('correct',payload->'answers'->i=item->'answer','explanation',item->'anchor'));i:=i+1;
 end loop;
 score:=100.0*earned/total;
 insert into tib_sweep_private.attempts(user_id,chapter,kind,payload,score) values(uid,chapter,'knowledge-check',payload,score);
 if score>=60 and not chapter=any(p.passed) then update tib_sweep_private.progress set passed=array_append(p.passed,chapter),updated_at=now() where user_id=uid returning * into p;end if;
 return jsonb_build_object('score',score,'earned',earned,'total',total,'passedAttempt',score>=60,'mode',p.mode,'passed',p.passed,'feedback',feedback);
end $$;
revoke all on function tib_sweep_private.assessment(text,integer,jsonb) from public,anon;
grant execute on function tib_sweep_private.assessment(text,integer,jsonb) to authenticated;
create function public.tib_sweep_assessment(action text,chapter integer default 0,payload jsonb default '{}') returns jsonb language sql security invoker set search_path='' as $$ select tib_sweep_private.assessment(action,chapter,payload); $$;
revoke all on function public.tib_sweep_assessment(text,integer,jsonb) from public,anon;
grant execute on function public.tib_sweep_assessment(text,integer,jsonb) to authenticated;
insert into tib_sweep_private.bank(chapter,questions) values (1,'[{"id":1,"prompt":"How would you define the control objective and support your conclusion?","anchor":"Before entering SAP, document the production system/client, company codes, population, point-in-time snapshot, risk pairing and exception criteria. Obtain reviewer agreement on the scope. Evidence: Signed scope worksheet, population definition and test criteria.","options":["Before entering SAP, document the production system/client, company codes, population, point-in-time snapshot, risk pairing and exception criteria. Obtain reviewer agreement on the scope.","Accept management’s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you grc access risk analysis and support your conclusion?","anchor":"Run GRC Access Risk Analysis at User Level, Report Type Detail, procure-to-pay ruleset. Capture the first run with Include Mitigated Risks unchecked. Run again with that setting checked; retain both selection screens and exports. Evidence: GRC selection criteria, timestamps, unmitigated and mitigated-inclusive result files and count reconciliation.","options":["Run GRC Access Risk Analysis at User Level, Report Type Detail, procure-to-pay ruleset. Capture the first run with Include Mitigated Risks unchecked. Run again with that setting checked; retain both selection screens and exports.","Accept management’s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you trace access in suim / pfcg and support your conclusion?","anchor":"In SAP GUI use /nSUIM to inspect Roles → By User Assignment. Use /nPFCG in Display mode for each relevant role, inspect Menu and Authorizations, and display authorization data. Do not modify roles. Evidence: SUIM role assignment listing and PFCG display-only authorization trace, with SID/client and capture date.","options":["In SAP GUI use /nSUIM to inspect Roles → By User Assignment. Use /nPFCG in Display mode for each relevant role, inspect Menu and Authorizations, and display authorization data. Do not modify roles.","Accept management’s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you assess the case conflicts and support your conclusion?","anchor":"Reconcile 41 case conflicts: 38 with recorded mitigation and 3 without. Trace the flagged user with both capabilities in one role. Record the three unmitigated conflicts as exceptions. Plan separate operating-effectiveness testing of the 38 recorded mitigations. Evidence: Conflict count reconciliation, exception register, role trace and mitigation test population.","options":["Reconcile 41 case conflicts: 38 with recorded mitigation and 3 without. Trace the flagged user with both capabilities in one role. Record the three unmitigated conflicts as exceptions. Plan separate operating-effectiveness testing of the 38 recorded mitigations.","Accept management’s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":5,"prompt":"How would you conclude and prepare for review and support your conclusion?","anchor":"Index the scope, two GRC exports, SUIM/PFCG traces and exception register. Conclude on the unmitigated SoD risk, recommend remediation of role design, and separately assess recorded mitigations. Clearly identify evidence gaps. Evidence: Workpaper conclusion, evidence index, exception owner, remediation recommendation and reviewer signoff.","options":["Index the scope, two GRC exports, SUIM/PFCG traces and exception register. Conclude on the unmitigated SoD risk, recommend remediation of role design, and separately assess recorded mitigations. Clearly identify evidence gaps.","Accept management’s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0}]'::jsonb);
insert into tib_sweep_private.bank(chapter,questions) values (2,'[{"id":1,"prompt":"How would you define change-control scope and support your conclusion?","anchor":"Document the production SID/client, testing period, full import population, change approval requirements, emergency process and exception conditions before opening SAP. Evidence: Control scope, approved period, authorised Basis group, population definition and exception criteria.","options":["Document the production SID/client, testing period, full import population, change approval requirements, emergency process and exception conditions before opening SAP.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you extract complete STMS import history and support your conclusion?","anchor":"Use /nSTMS → Import Overview → target production system → Import History. Set the testing period and preserve the selection criteria and raw export. Record transport ID, owner, import date/time and return code. Evidence: STMS selection screen, full import-history result, untouched raw export and reconciliation.","options":["Use /nSTMS → Import Overview → target production system → Import History. Set the testing period and preserve the selection criteria and raw export. Record transport ID, owner, import date/time and return code.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you trace transport objects and client settings and support your conclusion?","anchor":"Use /nSE01 in display mode to inspect sampled request attributes and object lists, including programs, table entries and configuration. Use /nSCC4 in display mode to record production client change/transport settings. Do not edit. Evidence: SE01 object-list captures per sampled transport and SCC4 production client settings.","options":["Use /nSE01 in display mode to inspect sampled request attributes and object lists, including programs, table entries and configuration. Use /nSCC4 in display mode to record production client change/transport settings. Do not edit.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you reconcile tickets and classify exceptions and support your conclusion?","anchor":"Match each STMS import to its change ticket. Compare approval timestamp with import timestamp and verify importer authorisation. Classify no ticket, approval after import or importer outside authorised Basis group. The Thornfield case has six imports without approved tickets, all over one weekend by one user. Retrospective Monday tickets do not prove prior approval. Evidence: Exception reconciliation with STMS timestamps, ticket history, importer group evidence and six case exceptions.","options":["Match each STMS import to its change ticket. Compare approval timestamp with import timestamp and verify importer authorisation. Classify no ticket, approval after import or importer outside authorised Basis group. The Thornfield case has six imports without approved tickets, all over one weekend by one user. Retrospective Monday tickets do not prove prior approval.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":5,"prompt":"How would you evidence, conclusion and reviewer challenge and support your conclusion?","anchor":"Index system status, STMS selection/results, SE01 sampled object lists, SCC4 settings and Excel reconciliation. Separate management explanation from evidence. Conclude that change control failed for six case imports during one incident without an emergency procedure. Recommend a defined emergency approval window, mandatory justification and post-implementation review. Evidence: THORNFIELD-B02-CH-01-SystemStatus; STMS-ImportHistory; SE01-ObjectList-[TransportID]; SCC4-ClientSettings; ExceptionClassification workbook, Reconciliation tab.","options":["Index system status, STMS selection/results, SE01 sampled object lists, SCC4 settings and Excel reconciliation. Separate management explanation from evidence. Conclude that change control failed for six case imports during one incident without an emergency procedure. Recommend a defined emergency approval window, mandatory justification and post-implementation review.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0}]'::jsonb);
insert into tib_sweep_private.bank(chapter,questions) values (3,'[{"id":1,"prompt":"How would you define policy and population and support your conclusion?","anchor":"Confirm manual-entry document types with Finance. Define system/client, company codes, period, posting-date versus entry-date scope, policy threshold and exception criteria. Do not select only routed entries. Evidence: Approved policy, test period, document types, threshold, population definition and reviewer scope.","options":["Confirm manual-entry document types with Finance. Define system/client, company codes, period, posting-date versus entry-date scope, policy threshold and exception criteria. Do not select only routed entries.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you build complete journal population and support your conclusion?","anchor":"Run /nFBL3N with company code, G/L and period filters. Supplement with /nSE16N on BKPF/BSEG where needed. Retain selection criteria, raw export and reconciled population. Distinguish posting date from entry date. Evidence: THORNFIELD-B03-BP-01-FBL3N-Selection-Result and reconciled raw population.","options":["Run /nFBL3N with company code, G/L and period filters. Supplement with /nSE16N on BKPF/BSEG where needed. Retain selection criteria, raw export and reconciled population. Distinguish posting date from entry date.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you trace approval and posting times and support your conclusion?","anchor":"Use /nFB03 to inspect document header, entered-by, document type and posting date. Use /nSWI1 to inspect workflow log, approver and timestamp. Compare approval time against posting time; retain evidence. Obtain threshold configuration and change history separately. Evidence: THORNFIELD-B03-BP-01-FB03-DocumentHeader; SWI1-WorkflowLog; ApprovalPostingGap-Calc.","options":["Use /nFB03 to inspect document header, entered-by, document type and posting date. Use /nSWI1 to inspect workflow log, approver and timestamp. Compare approval time against posting time; retain evidence. Obtain threshold configuration and change history separately.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you investigate threshold failure and support your conclusion?","anchor":"Compare documented policy threshold $10,000 with configured workflow threshold $100,000 from January 3 to June 6. Case: 412 manual entries totaling $18.4 million above policy threshold were not routed. The 25-entry sample drawn only from routed entries was clean but structurally excluded unrouted exceptions. Evidence: ThresholdConfig-ChangeHistory; full population reconciliation; 412 unrouted-entry case analysis; sample-selection critique.","options":["Compare documented policy threshold $10,000 with configured workflow threshold $100,000 from January 3 to June 6. Case: 412 manual entries totaling $18.4 million above policy threshold were not routed. The 25-entry sample drawn only from routed entries was clean but structurally excluded unrouted exceptions.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":5,"prompt":"How would you conclude and challenge and support your conclusion?","anchor":"Conclude that routing configuration did not match policy for the period and entries from $10,000 to $100,000 were excluded from the original routed-only sample. Recommend correcting threshold configuration, retesting previously unrouted entries and measuring approval-to-posting gaps. Index all five required exhibits and reviewer questions. Evidence: FBL3N-Selection-Result; FB03-DocumentHeader; SWI1-WorkflowLog; ThresholdConfig-ChangeHistory; ApprovalPostingGap-Calc.","options":["Conclude that routing configuration did not match policy for the period and entries from $10,000 to $100,000 were excluded from the original routed-only sample. Recommend correcting threshold configuration, retesting previously unrouted entries and measuring approval-to-posting gaps. Index all five required exhibits and reviewer questions.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0}]'::jsonb);
insert into tib_sweep_private.bank(chapter,questions) values (4,'[{"id":1,"prompt":"How would you define the new-hire population and support your conclusion?","anchor":"Obtain the HR new-hire and transfer population for the test period. Cross-reference users against active SU01 accounts. Define exceptions before sampling. Evidence: THORNFIELD-B04-AC-04-HR-NewHireReport.xlsx","options":["Obtain the HR new-hire and transfer population for the test period. Cross-reference users against active SU01 accounts. Define exceptions before sampling.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you compare requests with provisioned access and support your conclusion?","anchor":"Review GRC Access Request History for sampled new hires. Open /nSU01 in display mode and compare assigned roles and profiles with approved requests and the current role catalog. Evidence: THORNFIELD-B04-AC-04-AccessRequestHistory-Sample.png","options":["Review GRC Access Request History for sampled new hires. Open /nSU01 in display mode and compare assigned roles and profiles with approved requests and the current role catalog.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you validate role design in PFCG and support your conclusion?","anchor":"Open /nPFCG in display mode, inspect Menu, Authorizations and Display Authorization Data. Compare legacy composite role objects with current role design. Do not change roles. Evidence: THORNFIELD-B04-AC-04-PFCG-RoleCompare.png","options":["Open /nPFCG in display mode, inspect Menu, Authorizations and Display Authorization Data. Compare legacy composite role objects with current role design. Do not change roles.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you investigate two exceptions and support your conclusion?","anchor":"Thornfield case: of 20 sampled requests, 18 matched current design and 2 were provisioned using a composite role retired six months earlier. Both had the same approving manager. Investigate whether the approval interface still presents the retired role; record the manager question for reviewer discussion. Evidence: HR population, two GRC requests and PFCG comparison.","options":["Thornfield case: of 20 sampled requests, 18 matched current design and 2 were provisioned using a composite role retired six months earlier. Both had the same approving manager. Investigate whether the approval interface still presents the retired role; record the manager question for reviewer discussion.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":5,"prompt":"How would you conclude and package evidence and support your conclusion?","anchor":"Conclude that the new-hire provisioning control failed for 2 of 20 requests in the fictional case. Recommend removing the retired composite role from the approval interface and refreshing approver awareness. Index all three exhibits, reconcile sample to population and distinguish confirmed findings from reviewer questions. Evidence: THORNFIELD-B04-AC-04-HR-NewHireReport.xlsx; AccessRequestHistory-Sample.png; PFCG-RoleCompare.png","options":["Conclude that the new-hire provisioning control failed for 2 of 20 requests in the fictional case. Recommend removing the retired composite role from the approval interface and refreshing approver awareness. Index all three exhibits, reconcile sample to population and distinguish confirmed findings from reviewer questions.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0}]'::jsonb);
insert into tib_sweep_private.bank(chapter,questions) values (5,'[{"id":1,"prompt":"How would you define cutover window and scope and support your conclusion?","anchor":"Define Friday 18:00 through Sunday 24:00, included landscape systems, complete transport population and exception criteria. Capture source, client, preparer and extraction date. Evidence: THORNFIELD-B05-CH-02-SE03-CutoverPopulation.png","options":["Define Friday 18:00 through Sunday 24:00, included landscape systems, complete transport population and exception criteria. Capture source, client, preparer and extraction date.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you extract full SE03 population and support your conclusion?","anchor":"Open /nSE03 and use the applicable transport organizer tools/report to scope to the cutover window. Execute and export the complete transport list across included systems. Reconcile raw results. Evidence: THORNFIELD-B05-CH-02-SE03-CutoverPopulation.png","options":["Open /nSE03 and use the applicable transport organizer tools/report to scope to the cutover window. Execute and export the complete transport list across included systems. Reconcile raw results.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you select and test elevated-risk sample and support your conclusion?","anchor":"Document sample-size rationale. The case uses 40 transports rather than a typical 8–10. Match each sampled transport to standard or emergency change approvals and migration timestamps. Evidence: THORNFIELD-B05-CH-02-SampleSelection-Rationale.xlsx","options":["Document sample-size rationale. The case uses 40 transports rather than a typical 8–10. Match each sampled transport to standard or emergency change approvals and migration timestamps.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you investigate late emergency forms and support your conclusion?","anchor":"Case: 36 of 40 sampled transports had matching tickets within the required window. Four emergency justification forms were completed 1–3 hours after the 48-hour SLA, during the highest-volume overnight period. Compare approval, migration and evidence timestamps; do not treat ticket existence as timely approval. Evidence: THORNFIELD-B05-CH-02-LateEmergencyForms-Detail.xlsx","options":["Case: 36 of 40 sampled transports had matching tickets within the required window. Four emergency justification forms were completed 1–3 hours after the 48-hour SLA, during the highest-volume overnight period. Compare approval, migration and evidence timestamps; do not treat ticket existence as timely approval.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":5,"prompt":"How would you conclude and package evidence and support your conclusion?","anchor":"Conclude the control operated for 36 of 40 sampled transports; four emergency forms missed the required SLA. Recommend a second on-call approver during high-volume cutover windows. Index SE03 population, sample rationale and late-form detail. Separate management explanations from observed facts. Evidence: THORNFIELD-B05-CH-02-SE03-CutoverPopulation.png; SampleSelection-Rationale.xlsx; LateEmergencyForms-Detail.xlsx","options":["Conclude the control operated for 36 of 40 sampled transports; four emergency forms missed the required SLA. Recommend a second on-call approver during high-volume cutover windows. Index SE03 population, sample rationale and late-form detail. Separate management explanations from observed facts.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0}]'::jsonb);
insert into tib_sweep_private.bank(chapter,questions) values (6,'[{"id":1,"prompt":"How would you define acquired-entity control and support your conclusion?","anchor":"Document the acquisition date, nine-month review period, complete manual journal population, required reviewer and review evidence. Obtain written confirmation from the controller whether any system enforcement exists. Evidence: THORNFIELD-B06-BP-04-ControllerConfirmation-Email.pdf","options":["Document the acquisition date, nine-month review period, complete manual journal population, required reviewer and review evidence. Obtain written confirmation from the controller whether any system enforcement exists.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you obtain all monthly sign-offs and support your conclusion?","anchor":"Request all monthly reviewer sign-off emails for the full nine-month period, not a preselected sample. Reconcile the month-by-month evidence index to the acquisition period. Evidence: THORNFIELD-B06-BP-04-SignoffEmail-Population.xlsx","options":["Request all monthly reviewer sign-off emails for the full nine-month period, not a preselected sample. Reconcile the month-by-month evidence index to the acquisition period.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you test the underlying entries and support your conclusion?","anchor":"Select 25 manual journal entries from the six months with sign-off evidence and trace each to its reviewer and supporting review documentation. Record the sample''s limitation: it cannot demonstrate operation in the three missing months. Evidence: THORNFIELD-B06-BP-04-SampleTest-25Entries.xlsx","options":["Select 25 manual journal entries from the six months with sign-off evidence and trace each to its reviewer and supporting review documentation. Record the sample''s limitation: it cannot demonstrate operation in the three missing months.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you separate design gap from evidence gap and support your conclusion?","anchor":"Record controller confirmation that no system mechanism enforces review and the process is manual. Document the three months with no sign-off evidence as open for retrospective substantive testing. Do not treat lack of reported incidents as proof review occurred. Evidence: ControllerConfirmation-Email.pdf; SignoffEmail-Population.xlsx","options":["Record controller confirmation that no system mechanism enforces review and the process is manual. Document the three months with no sign-off evidence as open for retrospective substantive testing. Do not treat lack of reported incidents as proof review occurred.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":5,"prompt":"How would you conclude and assemble evidence and support your conclusion?","anchor":"Conclude that no system-enforced review exists and manual compensating-control evidence is missing for one-third of the period. Recommend system-enforced approval before group SAP migration and retrospective substantive testing for the three unevidenced months. Index controller confirmation, monthly sign-off population and 25-entry sample. Evidence: THORNFIELD-B06-BP-04-ControllerConfirmation-Email.pdf; SignoffEmail-Population.xlsx; SampleTest-25Entries.xlsx","options":["Conclude that no system-enforced review exists and manual compensating-control evidence is missing for one-third of the period. Recommend system-enforced approval before group SAP migration and retrospective substantive testing for the three unevidenced months. Index controller confirmation, monthly sign-off population and 25-entry sample.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0}]'::jsonb);
insert into tib_sweep_private.bank(chapter,questions) values (7,'[{"id":1,"prompt":"How would you define Procurement SoD risk and support your conclusion?","anchor":"Define Procurement population, period, risk IDs, release threshold and evidence of mitigating controls. Do not assume the Accounts Payable SoD ruleset covers Procurement. Evidence: THORNFIELD-B07-AC-05-GRC-ProcurementScope-Result.png","options":["Define Procurement population, period, risk IDs, release threshold and evidence of mitigating controls. Do not assume the Accounts Payable SoD ruleset covers Procurement.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you run risk analysis and validate usage and support your conclusion?","anchor":"Run Procurement-scoped Access Risk Analysis, preserve selection criteria and results, and inspect SUIM usage evidence for flagged users. Case: seven users flagged; two exercised both capabilities during the test period. Evidence: THORNFIELD-B07-AC-05-SUIM-UsageHistory-2Users.png","options":["Run Procurement-scoped Access Risk Analysis, preserve selection criteria and results, and inspect SUIM usage evidence for flagged users. Case: seven users flagged; two exercised both capabilities during the test period.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you interview and inspect role design and support your conclusion?","anchor":"Interview the business process owner about what the access allows. Trace relevant exceptions to SUIM/PFCG or underlying authorizations. Search similar role structures in Facilities and IT Procurement. Evidence: THORNFIELD-B07-AC-05-BPO-Interview-Notes.docx; THORNFIELD-B07-AC-05-CrossDept-RoleSearch.xlsx","options":["Interview the business process owner about what the access allows. Trace relevant exceptions to SUIM/PFCG or underlying authorizations. Search similar role structures in Facilities and IT Procurement.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you test PO creator versus releaser and support your conclusion?","anchor":"Compare PO creator with releaser for above-threshold purchase orders using EKKO and release-change evidence from CDHDR/CDPOS. Case: two of 46 POs were created and released by the same user, HKOWALSKI. Evidence: THORNFIELD-B07-AC-05-EKKO-CreatorVsReleaser.xlsx","options":["Compare PO creator with releaser for above-threshold purchase orders using EKKO and release-change evidence from CDHDR/CDPOS. Case: two of 46 POs were created and released by the same user, HKOWALSKI.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":5,"prompt":"How would you conclude and assemble evidence and support your conclusion?","anchor":"Document the previously untested Procurement SoD risk, seven flagged users, two who exercised both permissions, same pattern in two other departments and two same-user PO releases. Recommend extending the risk ruleset, remediating flagged roles and retesting non-finance departments. Index all five evidence items. Evidence: GRC ProcurementScope result; SUIM usage; BPO notes; cross-department search; EKKO creator-versus-releaser","options":["Document the previously untested Procurement SoD risk, seven flagged users, two who exercised both permissions, same pattern in two other departments and two same-user PO releases. Recommend extending the risk ruleset, remediating flagged roles and retesting non-finance departments. Index all five evidence items.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0}]'::jsonb);
insert into tib_sweep_private.bank(chapter,questions) values (8,'[{"id":1,"prompt":"How would you define vendor change control scope and support your conclusion?","anchor":"Define test period, target systems, vendor service accounts, approval requirements and contract reporting format. Preserve population and exception criteria before running SAP reports. Evidence: THORNFIELD-B08-CH-03-STMS-VendorAccount-Population.png","options":["Define test period, target systems, vendor service accounts, approval requirements and contract reporting format. Preserve population and exception criteria before running SAP reports.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you extract STMS and SM20 activity and support your conclusion?","anchor":"Use /nSTMS, Import Overview, target system, Import History and period filters; use /nSM20 for approved security audit log selection by user/time. Retain parameters, raw outputs and account mapping. Case: 31 transports in SAP logs. Evidence: THORNFIELD-B08-CH-03-STMS-VendorAccount-Population.png","options":["Use /nSTMS, Import Overview, target system, Import History and period filters; use /nSM20 for approved security audit log selection by user/time. Retain parameters, raw outputs and account mapping. Case: 31 transports in SAP logs.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you reconcile vendor self-reported log and support your conclusion?","anchor":"Obtain vendor change log for exactly the same period and reconcile transport IDs against SAP. Case: vendor reported 27 transports versus 31 in SAP. Four were classified as routine maintenance and omitted from vendor reporting. Evidence: THORNFIELD-B08-CH-03-VendorChangeLog-Export.xlsx; THORNFIELD-B08-CH-03-Reconciliation-VarianceDetail.xlsx","options":["Obtain vendor change log for exactly the same period and reconcile transport IDs against SAP. Case: vendor reported 27 transports versus 31 in SAP. Four were classified as routine maintenance and omitted from vendor reporting.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you independently verify approval evidence and support your conclusion?","anchor":"Trace sampled vendor transports to Thornfield''s STMS/SM20 evidence and CAB records; compare approval and import timestamps and check emergency justification windows. All 31 case transports had valid CAB tickets, despite vendor reporting omissions. Evidence: STMS vendor population and reconciled CAB references","options":["Trace sampled vendor transports to Thornfield''s STMS/SM20 evidence and CAB records; compare approval and import timestamps and check emergency justification windows. All 31 case transports had valid CAB tickets, despite vendor reporting omissions.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":5,"prompt":"How would you conclude and escalate contract issue and support your conclusion?","anchor":"Conclude vendor self-report understated actual activity by four transports, although all 31 were independently confirmed approved. Recommend vendor change log use Thornfield''s transport definition without unilateral exclusions. Flag contractual reporting interpretation for Legal/Procurement at renewal. Index population, vendor export and variance detail. Evidence: STMS population; vendor log export; reconciliation variance detail","options":["Conclude vendor self-report understated actual activity by four transports, although all 31 were independently confirmed approved. Recommend vendor change log use Thornfield''s transport definition without unilateral exclusions. Flag contractual reporting interpretation for Legal/Procurement at renewal. Index population, vendor export and variance detail.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0}]'::jsonb);
insert into tib_sweep_private.bank(chapter,questions) values (9,'[{"id":1,"prompt":"How would you define independent investigation and support your conclusion?","anchor":"Record the document, company code, fiscal year, period and exception criteria. Establish the original posting and relevant source records independently, not from the original summary. Evidence: THORNFIELD-B09-BP-05-SourceDataRequest-Email.pdf","options":["Record the document, company code, fiscal year, period and exception criteria. Establish the original posting and relevant source records independently, not from the original summary.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you reconstruct ledger and change history and support your conclusion?","anchor":"Use /nFBL3N with G/L and period, /nSE16N for BKPF/BSEG as appropriate and /nFB03 to inspect document header and change references. Case: two changes after posting, one amount adjustment and one cost-center change, neither in the original workpaper. Evidence: THORNFIELD-B09-BP-05-FB03-ChangeHistory.png","options":["Use /nFBL3N with G/L and period, /nSE16N for BKPF/BSEG as appropriate and /nFB03 to inspect document header and change references. Case: two changes after posting, one amount adjustment and one cost-center change, neither in the original workpaper.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you obtain underlying support directly and support your conclusion?","anchor":"Request raw underlying support from the original source-system owner, bypassing the preparer''s summary spreadsheet. Retain the direct request and source lineage. Do not assume a summary establishes completeness or accuracy. Evidence: THORNFIELD-B09-BP-05-SourceDataRequest-Email.pdf","options":["Request raw underlying support from the original source-system owner, bypassing the preparer''s summary spreadsheet. Retain the direct request and source lineage. Do not assume a summary establishes completeness or accuracy.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you independently recompute the estimate and support your conclusion?","anchor":"Recompute from source data where possible and preserve assumptions and calculations. The fictional case showed a 14 percent variance from the booked amount, outside the stated reasonable estimation range. Separate observations from allegations. Evidence: THORNFIELD-B09-BP-05-IndependentRecomputation.xlsx","options":["Recompute from source data where possible and preserve assumptions and calculations. The fictional case showed a 14 percent variance from the booked amount, outside the stated reasonable estimation range. Separate observations from allegations.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":5,"prompt":"How would you conclude and escalate appropriately and support your conclusion?","anchor":"Report the two undisclosed post-posting changes and 14 percent independent recomputation variance. Refer findings to Internal Audit for reportability determination, with Legal as appropriate. Require source data rather than prepared summaries for future support. Index change history, recomputation and source-data request. Evidence: FB03 change history; independent recomputation; source-data request","options":["Report the two undisclosed post-posting changes and 14 percent independent recomputation variance. Refer findings to Internal Audit for reportability determination, with Legal as appropriate. Require source data rather than prepared summaries for future support. Index change history, recomputation and source-data request.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0}]'::jsonb);
insert into tib_sweep_private.bank(chapter,questions) values (10,'[{"id":1,"prompt":"How would you define executive reporting completeness and support your conclusion?","anchor":"Define all findings from the tester''s working papers, reporting cut-off, evidence source and required severity descriptions. Distinguish control failures, documentation gaps, design issues, population issues and open reviewer questions. Evidence: THORNFIELD-B10-BP-07-Tracker-vs-WorkingNotes-Compare.xlsx","options":["Define all findings from the tester''s working papers, reporting cut-off, evidence source and required severity descriptions. Distinguish control failures, documentation gaps, design issues, population issues and open reviewer questions.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you reconcile findings to tracker and support your conclusion?","anchor":"Compare working notes and completed testing against the official tracker. Case: 19 findings identified, 17 correctly logged and two remaining only in working notes. Evidence: THORNFIELD-B10-BP-07-Tracker-vs-WorkingNotes-Compare.xlsx","options":["Compare working notes and completed testing against the official tracker. Case: 19 findings identified, 17 correctly logged and two remaining only in working notes.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you verify severity and evidence and support your conclusion?","anchor":"Trace each exception to SAP/source evidence and compare tracker severity to documented testing details. Case: one tracker entry understated severity. Record its correction with reviewer approval. Evidence: THORNFIELD-B10-BP-07-SeverityUnderstatement-Detail.docx","options":["Trace each exception to SAP/source evidence and compare tracker severity to documented testing details. Case: one tracker entry understated severity. Record its correction with reviewer approval.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you correct before reporting cycle and support your conclusion?","anchor":"Transfer both missing findings into the tracker and correct the understated severity. Case: all three issues were corrected before the next reporting cycle. State open items honestly rather than rounding progress upward. Evidence: Corrected tracker and severity detail","options":["Transfer both missing findings into the tracker and correct the understated severity. Case: all three issues were corrected before the next reporting cycle. State open items honestly rather than rounding progress upward.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":5,"prompt":"How would you conclude and improve reporting process and support your conclusion?","anchor":"Conclude two findings were missing and one severity understated at review; all three corrected before the next cycle. Recommend same-day tracker entry for every finding, rather than batching updates before reporting deadlines. Index reconciliation and severity evidence. Evidence: THORNFIELD-B10-BP-07-Tracker-vs-WorkingNotes-Compare.xlsx; THORNFIELD-B10-BP-07-SeverityUnderstatement-Detail.docx","options":["Conclude two findings were missing and one severity understated at review; all three corrected before the next cycle. Recommend same-day tracker entry for every finding, rather than batching updates before reporting deadlines. Index reconciliation and severity evidence.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0}]'::jsonb);
insert into tib_sweep_private.bank(chapter,questions) values (11,'[{"id":1,"prompt":"How would you define SEC response evidence scope and support your conclusion?","anchor":"Define the complete 12-month period, four referenced controls and ten-day response window. Request unedited source evidence rather than a curated subset. Capture source, owner, dates and exception conditions. Evidence: THORNFIELD-B11-BP-08-EvidenceFile-Index.xlsx","options":["Define the complete 12-month period, four referenced controls and ten-day response window. Request unedited source evidence rather than a curated subset. Capture source, owner, dates and exception conditions.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you assemble evidence by month and control and support your conclusion?","anchor":"Build a month-by-control evidence index, preserving source references and filenames. Compare each required control/month to supporting documentation and identify missing items. Evidence: THORNFIELD-B11-BP-08-EvidenceFile-Index.xlsx","options":["Build a month-by-control evidence index, preserving source references and filenames. Compare each required control/month to supporting documentation and identify missing items.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you escalate missing month immediately and support your conclusion?","anchor":"At initial assembly, month seven''s support was missing. Flag the gap to the Senior Lead on day two of the ten-day response window and preserve the escalation message. Do not conceal the gap pending recovery. Evidence: THORNFIELD-B11-BP-08-GapFlag-Day2-Email.pdf","options":["At initial assembly, month seven''s support was missing. Flag the gap to the Senior Lead on day two of the ten-day response window and preserve the escalation message. Do not conceal the gap pending recovery.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you recover and verify supporting documentation and support your conclusion?","anchor":"Locate the month-seven documents in the archived mailbox. Confirm relevance, dates, control coverage and source, then add them to the index before submission. Preserve the recovered originals and retrieval history. Evidence: THORNFIELD-B11-BP-08-Month7-Recovered-Documentation.pdf","options":["Locate the month-seven documents in the archived mailbox. Confirm relevance, dates, control coverage and source, then add them to the index before submission. Preserve the recovered originals and retrieval history.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":5,"prompt":"How would you conclude and improve retention and support your conclusion?","anchor":"Conclude one month was initially missing, escalated promptly and recovered before submission. Recommend a standing evidence-retention checklist for SEC-reportable controls. Index the 12-month/four-control file, day-two escalation and recovered documents. Evidence: EvidenceFile-Index.xlsx; GapFlag-Day2-Email.pdf; Month7-Recovered-Documentation.pdf","options":["Conclude one month was initially missing, escalated promptly and recovered before submission. Recommend a standing evidence-retention checklist for SEC-reportable controls. Index the 12-month/four-control file, day-two escalation and recovered documents.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0}]'::jsonb);
insert into tib_sweep_private.bank(chapter,questions) values (12,'[{"id":1,"prompt":"How would you define disclosure escalation test and support your conclusion?","anchor":"Define incident period, detection and containment timestamps, documented escalation policy and committee notification requirements. Capture system, client, sources, evidence owner and test criteria before extraction. Evidence: THORNFIELD-B12-BP-02-IncidentRecord.pdf","options":["Define incident period, detection and containment timestamps, documented escalation policy and committee notification requirements. Capture system, client, sources, evidence owner and test criteria before extraction.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you validate security logs and retention and support your conclusion?","anchor":"Review SM21 system log, SM20 security audit log and SM19 audit configuration and retention for the incident period. Retain selection criteria, screenshots and completeness limitations. Evidence: THORNFIELD-B12-BP-02-SM21-Extract.png; THORNFIELD-B12-BP-02-SM20-Result.png; THORNFIELD-B12-BP-02-SM19-Configuration.png","options":["Review SM21 system log, SM20 security audit log and SM19 audit configuration and retention for the incident period. Retain selection criteria, screenshots and completeness limitations.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you reconstruct incident timeline and support your conclusion?","anchor":"Obtain the original security incident record rather than relying on committee minutes. Reconstruct detection, containment and escalation timestamps. Case: 23 days elapsed before the incident reached the disclosure committee. Evidence: THORNFIELD-B12-BP-02-IncidentRecord.pdf","options":["Obtain the original security incident record rather than relying on committee minutes. Reconstruct detection, containment and escalation timestamps. Case: 23 days elapsed before the incident reached the disclosure committee.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you check related production changes and criteria and support your conclusion?","anchor":"Cross-reference incident dates to STMS production import history; no related production change was identified in the case. Review policy wording: ''escalate significant incidents'' lacked specific actionable thresholds. Evidence: THORNFIELD-B12-BP-02-STMS-CrossReference.png","options":["Cross-reference incident dates to STMS production import history; no related production change was identified in the case. Review policy wording: ''escalate significant incidents'' lacked specific actionable thresholds.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":5,"prompt":"How would you conclude without making legal determination and support your conclusion?","anchor":"Document the 23-day delay and nonspecific criteria as the supported control finding. Note Security''s view that impact was immaterial without adopting it as the test conclusion. Refer any disclosure obligation and materiality determination to Legal and the disclosure committee. Index all five evidence items. Evidence: SM21 extract; SM20 result; SM19 configuration; incident record; STMS cross-reference","options":["Document the 23-day delay and nonspecific criteria as the supported control finding. Note Security''s view that impact was immaterial without adopting it as the test conclusion. Refer any disclosure obligation and materiality determination to Legal and the disclosure committee. Index all five evidence items.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0}]'::jsonb);
insert into tib_sweep_private.bank(chapter,questions) values (13,'[{"id":1,"prompt":"How would you define Fiori tile access assertion and support your conclusion?","anchor":"Define test user, assigned business catalogs, backend roles, target sensitive tile and scope. Use /UI2/FLPD-CUST and Manage Launchpad Pages to identify tiles. Preserve system/client, date and selection evidence. Evidence: THORNFIELD-B13-AC-06-FLPD-TileInventory.png","options":["Define test user, assigned business catalogs, backend roles, target sensitive tile and scope. Use /UI2/FLPD-CUST and Manage Launchpad Pages to identify tiles. Preserve system/client, date and selection evidence.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you identify tile target and service and support your conclusion?","anchor":"Record each sensitive tile''s target mapping and OData service, then compare with the expected catalog assignment. In the case, the test user saw a vendor-payment-adjacent tile not expected for their role. Evidence: THORNFIELD-B13-AC-06-FLPD-TileInventory.png","options":["Record each sensitive tile''s target mapping and OData service, then compare with the expected catalog assignment. In the case, the test user saw a vendor-payment-adjacent tile not expected for their role.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you compare SU24 and PFCG checks and support your conclusion?","anchor":"Use /nSU24 in display mode to inspect authorization proposals and checks for the underlying OData service. Use /nPFCG in display mode to review assigned backend role authorizations. Case: SU24 identified the same authorization object as the classic transaction. Evidence: THORNFIELD-B13-AC-06-SU24-ODataAuthCheck.png","options":["Use /nSU24 in display mode to inspect authorization proposals and checks for the underlying OData service. Use /nPFCG in display mode to review assigned backend role authorizations. Case: SU24 identified the same authorization object as the classic transaction.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you reproduce the user action and support your conclusion?","anchor":"Log in as the approved test user and attempt the sensitive operation through the tile. Preserve evidence of the launch and backend block. The tile launched, but backend authorization prevented the action. Evidence: THORNFIELD-B13-AC-06-LiveTest-BlockedAttempt.png","options":["Log in as the approved test user and attempt the sensitive operation through the tile. Preserve evidence of the launch and backend block. The tile launched, but backend authorization prevented the action.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":5,"prompt":"How would you classify and remediate design inconsistency and support your conclusion?","anchor":"Conclude backend security correctly blocked the sensitive action, while front-end catalog/group assignment exposed a tile unnecessarily. Recommend aligning Fiori catalog assignments with backend role design; document the issue separately from any proven access-control failure. Evidence: FLPD tile inventory; SU24 OData authorization check; live blocked attempt","options":["Conclude backend security correctly blocked the sensitive action, while front-end catalog/group assignment exposed a tile unnecessarily. Recommend aligning Fiori catalog assignments with backend role design; document the issue separately from any proven access-control failure.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0}]'::jsonb);
insert into tib_sweep_private.bank(chapter,questions) values (14,'[{"id":1,"prompt":"How would you define continuous monitoring assertion and support your conclusion?","anchor":"Record the control matrix description, rule data source, filters, deficiency criteria, period and rule owner. Compare the actual GRC Process Control definition with the documented assertion. Evidence: THORNFIELD-B14-BP-03-RuleDefinition.png; THORNFIELD-B14-BP-03-RuleVsDescription-Comparison.xlsx","options":["Record the control matrix description, rule data source, filters, deficiency criteria, period and rule owner. Compare the actual GRC Process Control definition with the documented assertion.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you examine execution history and support your conclusion?","anchor":"Extract execution history for the entire period, including scheduled runs and result counts. In the case, six consecutive weeks showed clean results after a data-source change caused the rule to evaluate an empty or incorrect population. Evidence: THORNFIELD-B14-BP-03-ExecutionHistory.png","options":["Extract execution history for the entire period, including scheduled runs and result counts. In the case, six consecutive weeks showed clean results after a data-source change caused the rule to evaluate an empty or incorrect population.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you trace unauthorized rule change and support your conclusion?","anchor":"Review rule change history for timestamp, person and altered data source. Compare with control matrix and approval records. The data source was changed without documented review or approval. Evidence: THORNFIELD-B14-BP-03-ChangeHistory.png","options":["Review rule change history for timestamp, person and altered data source. Compare with control matrix and approval records. The data source was changed without documented review or approval.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you independently test a qualifying transaction and support your conclusion?","anchor":"Use /nSE16N and relevant transaction records to identify a transaction meeting the documented rule condition. Compare against the rule''s output. In the case, the qualifying transaction was not flagged after the source change. Evidence: THORNFIELD-B14-BP-03-InjectionTest-Evidence.png","options":["Use /nSE16N and relevant transaction records to identify a transaction meeting the documented rule condition. Compare against the rule''s output. In the case, the qualifying transaction was not flagged after the source change.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":5,"prompt":"How would you record two linked findings and support your conclusion?","anchor":"Conclude monitoring failed from the data-source change date, and rule configuration changes lacked review/approval. Recommend restoring the source and validating missed-period transactions, plus change approval and periodic rule effectiveness testing. Preserve five evidence exhibits. Evidence: RuleDefinition.png; ExecutionHistory.png; ChangeHistory.png; InjectionTest-Evidence.png; RuleVsDescription-Comparison.xlsx","options":["Conclude monitoring failed from the data-source change date, and rule configuration changes lacked review/approval. Recommend restoring the source and validating missed-period transactions, plus change approval and periodic rule effectiveness testing. Preserve five evidence exhibits.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0}]'::jsonb);
insert into tib_sweep_private.bank(chapter,questions) values (15,'[{"id":1,"prompt":"How would you define risk mitigation assertion and support your conclusion?","anchor":"Export the full risk register, preserving mitigation status, linked control ID, period, source and owner. Define invalid reference and inactive control exception criteria before testing. Evidence: THORNFIELD-B15-BP-06-RiskRegister-Export.xlsx","options":["Export the full risk register, preserving mitigation status, linked control ID, period, source and owner. Define invalid reference and inactive control exception criteria before testing.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you reconcile control references and support your conclusion?","anchor":"Compare all 64 references against the current active control inventory and control testing records. The case resolves 58 and identifies six unresolved references. Evidence: THORNFIELD-B15-BP-06-ControlInventory-CrossCheck.xlsx","options":["Compare all 64 references against the current active control inventory and control testing records. The case resolves 58 and identifies six unresolved references.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you investigate six broken references and support your conclusion?","anchor":"Trace all six exceptions through prior inventory and retirement records. Three linked controls were retired during an earlier remediation cycle; three IDs had never existed. Preserve item-level evidence and do not assume a different control automatically mitigates the risk. Evidence: THORNFIELD-B15-BP-06-BrokenReference-Detail.docx","options":["Trace all six exceptions through prior inventory and retirement records. Three linked controls were retired during an earlier remediation cycle; three IDs had never existed. Preserve item-level evidence and do not assume a different control automatically mitigates the risk.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you assess risk status and governance and support your conclusion?","anchor":"For each broken reference, assess underlying risk and search for independently supported replacement controls. Until reassessed, treat the six as unmitigated. Investigate why retirement did not update the risk register. Evidence: RiskRegister-Export.xlsx; ControlInventory-CrossCheck.xlsx; BrokenReference-Detail.docx","options":["For each broken reference, assess underlying risk and search for independently supported replacement controls. Until reassessed, treat the six as unmitigated. Investigate why retirement did not update the risk register.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":5,"prompt":"How would you conclude and prevent recurrence and support your conclusion?","anchor":"Conclude six of 64 mitigated risks lack valid active controls, with three retired and three nonexistent references. Recommend fresh risk assessments and a control-retirement process requiring simultaneous updates to the risk register. Index all three evidence exhibits. Evidence: THORNFIELD-B15-BP-06-RiskRegister-Export.xlsx; THORNFIELD-B15-BP-06-ControlInventory-CrossCheck.xlsx; THORNFIELD-B15-BP-06-BrokenReference-Detail.docx","options":["Conclude six of 64 mitigated risks lack valid active controls, with three retired and three nonexistent references. Recommend fresh risk assessments and a control-retirement process requiring simultaneous updates to the risk register. Index all three evidence exhibits.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0}]'::jsonb);
insert into tib_sweep_private.bank(chapter,questions) values (16,'[{"id":1,"prompt":"How would you establish complete firefighter population and support your conclusion?","anchor":"Use GRC Reports and Analytics to extract the complete firefighter session log for the defined period. Leave firefighter ID blank so the population includes every ID. Retain selection criteria and result. Evidence: THORNFIELD-B16-AC-02-SessionLog-Selection-Result.png","options":["Use GRC Reports and Analytics to extract the complete firefighter session log for the defined period. Leave firefighter ID blank so the population includes every ID. Retain selection criteria and result.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you inspect session reason codes and support your conclusion?","anchor":"Review a sample of reason codes from the 31 sessions, distinguishing genuine business justification from vague free-text descriptions. Record the session IDs and reviewer observations. Evidence: THORNFIELD-B16-AC-02-ReasonCode-Sample.png","options":["Review a sample of reason codes from the 31 sessions, distinguishing genuine business justification from vague free-text descriptions. Record the session IDs and reviewer observations.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you reconcile independent review evidence and support your conclusion?","anchor":"Extract firefighter log-review records for the same period and reconcile against the full session population. Case: 31 sessions but only two review records, leaving 29 without review evidence. Evidence: THORNFIELD-B16-AC-02-ReviewReport-Count.png; THORNFIELD-B16-AC-02-Reconciliation.xlsx","options":["Extract firefighter log-review records for the same period and reconcile against the full session population. Case: 31 sessions but only two review records, leaving 29 without review evidence.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you verify claimed automated interface exclusion and support your conclusion?","anchor":"Management proposed excluding one firefighter ID as an automated interface. Inspect the ID in /nSU01 display mode, Logon Data and User Type. The case shows User Type: Dialog, meaning the proposed exclusion is not supported. Evidence: THORNFIELD-B16-AC-02-SU01-UserType.png","options":["Management proposed excluding one firefighter ID as an automated interface. Inspect the ID in /nSU01 display mode, Logon Data and User Type. The case shows User Type: Dialog, meaning the proposed exclusion is not supported.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":5,"prompt":"How would you conclude emergency access review failure and support your conclusion?","anchor":"Conclude the detective review control did not operate for 29 of 31 sessions. Keep the Dialog user in the population and document the unsupported exclusion proposal. Recommend complete timely independent controller review and reconciliation monitoring. Evidence: SessionLog-Selection-Result.png; ReasonCode-Sample.png; ReviewReport-Count.png; SU01-UserType.png; Reconciliation.xlsx","options":["Conclude the detective review control did not operate for 29 of 31 sessions. Keep the Dialog user in the population and document the unsupported exclusion proposal. Recommend complete timely independent controller review and reconciliation monitoring.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0}]'::jsonb);
insert into tib_sweep_private.bank(chapter,questions) values (17,'[{"id":1,"prompt":"How would you define HR leaver population and support your conclusion?","anchor":"Use HR termination records as the population, not IT deprovisioning requests. Record dates, SAP IDs and scope. Evidence: THORNFIELD-B17-AC-03-HR-TerminationList.xlsx","options":["Use HR termination records as the population, not IT deprovisioning requests. Record dates, SAP IDs and scope.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you inspect account status and support your conclusion?","anchor":"Use SU01 display mode to capture user type, validity and lock status for selected leavers. Evidence: THORNFIELD-B17-AC-03-SU01-LogonData.png","options":["Use SU01 display mode to capture user type, validity and lock status for selected leavers.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you check last logon and support your conclusion?","anchor":"Run SUIM Users by Logon Date and Password Change or authorized RSUSR200 using the full HR list. Save selections and export results. Evidence: THORNFIELD-B17-AC-03-SUIM-Selection-Result.png; THORNFIELD-B17-AC-03-ExportedPopulation.xlsx","options":["Run SUIM Users by Logon Date and Password Change or authorized RSUSR200 using the full HR list. Save selections and export results.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you maintain two exception columns and support your conclusion?","anchor":"Column A lists accounts still active; source does not provide a numeric count. Column B records at least one logon five weeks after termination and four days before testing. Do not add columns together. Evidence: THORNFIELD-B17-AC-03-TwoColumnExceptionList.xlsx","options":["Column A lists accounts still active; source does not provide a numeric count. Column B records at least one logon five weeks after termination and four days before testing. Do not add columns together.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":5,"prompt":"How would you report evidence-based conclusion and support your conclusion?","anchor":"Record management''s contractor-return explanation as reviewer discussion, not automatic closure. Highlight post-termination activity as the more severe issue and recommend timely revocation. Evidence: HR-TerminationList.xlsx; SU01-LogonData.png; SUIM-Selection-Result.png; ExportedPopulation.xlsx; TwoColumnExceptionList.xlsx","options":["Record management''s contractor-return explanation as reviewer discussion, not automatic closure. Highlight post-termination activity as the more severe issue and recommend timely revocation.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0}]'::jsonb);
insert into tib_sweep_private.bank(chapter,questions) values (18,'[{"id":1,"prompt":"How would you expected backup schedule and support your conclusion?","anchor":"Establish 365 expected nightly backup runs before examining the logs. Evidence: THORNFIELD-B18-OPS-01-ExpectedCount-Note.xlsx","options":["Establish 365 expected nightly backup runs before examining the logs.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you review DB13 calendar and support your conclusion?","anchor":"Inspect the complete DB13 calendar and retain period and selection evidence. Evidence: THORNFIELD-B18-OPS-01-DB13-Calendar.png","options":["Inspect the complete DB13 calendar and retain period and selection evidence.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you compare DB12 and SM37 and support your conclusion?","anchor":"Compare DB12 backup log and SM37 jobs with 365 expected. Case: 364 completed and one missing. Evidence: THORNFIELD-B18-OPS-01-DB12-Log.png; THORNFIELD-B18-OPS-01-SM37-Selection-Result.png","options":["Compare DB12 backup log and SM37 jobs with 365 expected. Case: 364 completed and one missing.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you find restoration testing and support your conclusion?","anchor":"Search for restoration test evidence for the period. The case found none. Document the search and sources. Evidence: THORNFIELD-B18-OPS-01-RestorationTestSearch-Note.docx","options":["Search for restoration test evidence for the period. The case found none. Document the search and sources.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":5,"prompt":"How would you record two distinct issues and support your conclusion?","anchor":"Report one missing backup run and the separate design deficiency: no restoration testing. Recommend periodic documented restore tests. Evidence: ExpectedCount-Note.xlsx; DB13-Calendar.png; DB12-Log.png; SM37-Selection-Result.png; RestorationTestSearch-Note.docx","options":["Report one missing backup run and the separate design deficiency: no restoration testing. Recommend periodic documented restore tests.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0}]'::jsonb);
insert into tib_sweep_private.bank(chapter,questions) values (19,'[{"id":1,"prompt":"How would you obtain source transmissions and support your conclusion?","anchor":"Record the quarterly Warehouse Management System transmission population before querying SAP. The source reports 41,206 goods movements. Evidence: THORNFIELD-B19-OPS-02-SourceCount-Reference.xlsx","options":["Record the quarterly Warehouse Management System transmission population before querying SAP. The source reports 41,206 goods movements.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you review interface errors and support your conclusion?","anchor":"Review SM58 errors by date and age, and inspect SMQ1 and SMQ2 queue counts. Record items exceeding the target resolution window. Evidence: THORNFIELD-B19-OPS-02-SM58-Selection-Result.png","options":["Review SM58 errors by date and age, and inspect SMQ1 and SMQ2 queue counts. Record items exceeding the target resolution window.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you examine IDoc errors and support your conclusion?","anchor":"Filter WE02 for IDoc statuses 51 and 64 in the test period and retain the error population. Cross-check with SM58 and queue findings. Evidence: THORNFIELD-B19-OPS-02-WE02-ErrorPopulation.png","options":["Filter WE02 for IDoc statuses 51 and 64 in the test period and retain the error population. Cross-check with SM58 and queue findings.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you reconcile counts and value and support your conclusion?","anchor":"Compare 41,206 source movements to 41,192 SAP postings: a gap of 14. Assess value and concentration by date, plant and material type; the case gap was concentrated. Evidence: THORNFIELD-B19-OPS-02-Reconciliation-ValueAnalysis.xlsx","options":["Compare 41,206 source movements to 41,192 SAP postings: a gap of 14. Assess value and concentration by date, plant and material type; the case gap was concentrated.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":5,"prompt":"How would you document interface control conclusion and support your conclusion?","anchor":"Document the 14-movement concentrated reconciliation gap and aged SM58 errors. Challenge the unsupported claim that a 0.03 percent difference is within tolerance without item-level value and composition analysis. Evidence: SourceCount-Reference.xlsx; SM58-Selection-Result.png; WE02-ErrorPopulation.png; Reconciliation-ValueAnalysis.xlsx","options":["Document the 14-movement concentrated reconciliation gap and aged SM58 errors. Challenge the unsupported claim that a 0.03 percent difference is within tolerance without item-level value and composition analysis.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0}]'::jsonb);
insert into tib_sweep_private.bank(chapter,questions) values (20,'[{"id":1,"prompt":"How would you inventory custom transactions and support your conclusion?","anchor":"Search SE93 for custom transaction namespaces. Case inventory: 112 custom transactions; nine affect sensitive vendor, payment or journal processes. Evidence: THORNFIELD-B20-CH-04-SE93-CustomTxnInventory.xlsx","options":["Search SE93 for custom transaction namespaces. Case inventory: 112 custom transactions; nine affect sensitive vendor, payment or journal processes.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you compare authorization checks and support your conclusion?","anchor":"Review linked ABAP program in display mode and compare its checks against SU24. ZFI-VENDOR-QUICK omitted F-LFA1-BUK and checked only general activity. Evidence: THORNFIELD-B20-CH-04-AuthorityCheck-Comparison.xlsx","options":["Review linked ABAP program in display mode and compare its checks against SU24. ZFI-VENDOR-QUICK omitted F-LFA1-BUK and checked only general activity.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you evaluate restricted-user test and support your conclusion?","anchor":"Review the approved restricted-user test evidence. In the case, the user changed vendor bank details via the custom transaction despite a standard transaction restriction. This is a confirmed control failure. Evidence: THORNFIELD-B20-CH-04-LiveTest-UnauthorizedChange.png","options":["Review the approved restricted-user test evidence. In the case, the user changed vendor bank details via the custom transaction despite a standard transaction restriction. This is a confirmed control failure.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you review broader SCI results and support your conclusion?","anchor":"Review SCI Code Inspector findings for the custom code inventory. Two additional transactions from the same developer showed the omitted-check pattern; distinguish code findings from the separately confirmed live bypass. Evidence: THORNFIELD-B20-CH-04-SCI-PatternScan-Result.png","options":["Review SCI Code Inspector findings for the custom code inventory. Two additional transactions from the same developer showed the omitted-check pattern; distinguish code findings from the separately confirmed live bypass.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":5,"prompt":"How would you recommend immediate and systemic remediation and support your conclusion?","anchor":"Recommend remediation of all three affected custom transactions and a mandatory SU24-based authorization review gate for sensitive custom code. Record the common developer and code-review training issue. Evidence: SE93-CustomTxnInventory.xlsx; AuthorityCheck-Comparison.xlsx; LiveTest-UnauthorizedChange.png; SCI-PatternScan-Result.png","options":["Recommend remediation of all three affected custom transactions and a mandatory SU24-based authorization review gate for sensitive custom code. Record the common developer and code-review training issue.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0}]'::jsonb);
insert into tib_sweep_private.bank(chapter,questions) values (21,'[{"id":1,"prompt":"How would you establish retention policy and support your conclusion?","anchor":"Review the former-employee personal-data retention policy. The documented limit is three years after termination. Evidence: THORNFIELD-B21-LC-01-RetentionPolicy-Document.pdf","options":["Review the former-employee personal-data retention policy. The documented limit is three years after termination.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you extract records in SE16N and support your conclusion?","anchor":"Use SE16N display to extract relevant former-employee records and date fields. Retain selection criteria and the raw export. Evidence: THORNFIELD-B21-LC-01-SE16N-PopulationExport.xlsx","options":["Use SE16N display to extract relevant former-employee records and date fields. Retain selection criteria and the raw export.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you check anonymization and archive flags and support your conclusion?","anchor":"Review the 214 overdue records for anonymization or archival indicators. The case records no such flags. Evidence: THORNFIELD-B21-LC-01-SE16N-PopulationExport.xlsx","options":["Review the 214 overdue records for anonymization or archival indicators. The case records no such flags.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you examine technical enforcement and support your conclusion?","anchor":"Inspect available ILM configuration and scheduled retention jobs. The case found no ILM setup or scheduled enforcement job. Evidence: THORNFIELD-B21-LC-01-ILM-ConfigCheck-NotFound.png","options":["Inspect available ILM configuration and scheduled retention jobs. The case found no ILM setup or scheduled enforcement job.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":5,"prompt":"How would you conclude and recommend remediation and support your conclusion?","anchor":"Report 214 former-employee records exceeding the three-year limit and no system-side enforcement. Recommend ILM or equivalent scheduled purge/anonymization and remediation of the 214-record backlog. Evidence: RetentionPolicy-Document.pdf; SE16N-PopulationExport.xlsx; ILM-ConfigCheck-NotFound.png","options":["Report 214 former-employee records exceeding the three-year limit and no system-side enforcement. Recommend ILM or equivalent scheduled purge/anonymization and remediation of the 214-record backlog.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0}]'::jsonb);
insert into tib_sweep_private.bank(chapter,questions) values (22,'[{"id":1,"prompt":"How would you inventory RFC connections and support your conclusion?","anchor":"Review SM59 active RFC destinations. Case: 12 active connections, three carrying material transaction volumes. Evidence: THORNFIELD-B22-LC-02-SM59-RFCInventory.xlsx","options":["Review SM59 active RFC destinations. Case: 12 active connections, three carrying material transaction volumes.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you analyze transaction volume and support your conclusion?","anchor":"Use ST03N and SE16N to analyze a representative period. Three connections exceed 500 transactions daily. Evidence: THORNFIELD-B22-LC-02-ST03N-VolumeAnalysis.xlsx","options":["Use ST03N and SE16N to analyze a representative period. Three connections exceed 500 transactions daily.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you review USMM classification and support your conclusion?","anchor":"Review USMM measurement results. All three material connections are classified technical/background, rather than named business users. Evidence: THORNFIELD-B22-LC-02-USMM-Classification-Export.png","options":["Review USMM measurement results. All three material connections are classified technical/background, rather than named business users.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you identify business-equivalent transactions and support your conclusion?","anchor":"Review transaction content. The three connections perform order creation and invoice posting indirectly through SAP. Evidence: THORNFIELD-B22-LC-02-ST03N-VolumeAnalysis.xlsx","options":["Review transaction content. The three connections perform order creation and invoice posting indirectly through SAP.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":5,"prompt":"How would you escalate formal licensing assessment and support your conclusion?","anchor":"Document three material RFC connections with business-equivalent activity and technical classification. Escalate to IT asset management, Legal and licensing counsel before license true-up; do not assert a final license liability. Evidence: SM59-RFCInventory.xlsx; ST03N-VolumeAnalysis.xlsx; USMM-Classification-Export.png","options":["Document three material RFC connections with business-equivalent activity and technical classification. Escalate to IT asset management, Legal and licensing counsel before license true-up; do not assert a final license liability.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0}]'::jsonb);
insert into tib_sweep_private.bank(chapter,questions) values (23,'[{"id":1,"prompt":"How would you define expected job executions and support your conclusion?","anchor":"Read the job schedule and set expected runs before opening SM37. A daily job over 90 days implies 90 expected executions. Evidence: THORNFIELD-B23-AP-01-SM36-JobDefinition-Gap.png","options":["Read the job schedule and set expected runs before opening SM37. A daily job over 90 days implies 90 expected executions.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you identify misleading SM37 filter and support your conclusion?","anchor":"Run SM37 with job name and user wildcarded. The initial case view excludes Cancelled and misleadingly appears clean with 90 entries. Evidence: THORNFIELD-B23-AP-01-SM37-InitialResult-Unticked.png","options":["Run SM37 with job name and user wildcarded. The initial case view excludes Cancelled and misleadingly appears clean with 90 entries.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you include all job statuses and support your conclusion?","anchor":"Repeat SM37 with every status selected, including Cancelled. The case reports 84 completed and six cancelled. Inspect cancelled job logs and steps. Evidence: THORNFIELD-B23-AP-01-SM37-FullResult-CancelledIncluded.png","options":["Repeat SM37 with every status selected, including Cancelled. The case reports 84 completed and six cancelled. Inspect cancelled job logs and steps.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you detect runs that never occurred and support your conclusion?","anchor":"Review SM36 job definition and schedule. A mid-period configuration change left the job not re-released, causing a four-day period without executions. Preserve this as a separate gap observation. Evidence: THORNFIELD-B23-AP-01-SM36-JobDefinition-Gap.png","options":["Review SM36 job definition and schedule. A mid-period configuration change left the job not re-released, causing a four-day period without executions. Preserve this as a separate gap observation.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":5,"prompt":"How would you conclude on monitoring weaknesses and support your conclusion?","anchor":"Document six cancellations and a four-day nonexecution gap. Source case figures are reported as observed; reconcile their timeline rather than treating the counts as additive. Recommend expected-versus-actual monitoring and default inclusion of Cancelled. Evidence: SM37-InitialResult-Unticked.png; SM37-FullResult-CancelledIncluded.png; SM36-JobDefinition-Gap.png","options":["Document six cancellations and a four-day nonexecution gap. Source case figures are reported as observed; reconcile their timeline rather than treating the counts as additive. Recommend expected-versus-actual monitoring and default inclusion of Cancelled.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0}]'::jsonb);
insert into tib_sweep_private.bank(chapter,questions) values (24,'[{"id":1,"prompt":"How would you plant matching settings and support your conclusion?","anchor":"Review EKPO WEPOS and REPOS by plant. Of 22 plants, 18 use three-way and four use two-way matching. Evidence: THORNFIELD-B24-AP-02-EKPO-PlantConfig-Extract.xlsx","options":["Review EKPO WEPOS and REPOS by plant. Of 22 plants, 18 use three-way and four use two-way matching.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":2,"prompt":"How would you invoice timing and support your conclusion?","anchor":"Sample 20 invoices at the four two-way plants. Three show goods receipts posted after payment. Evidence: THORNFIELD-B24-AP-02-POHistory-Sample20.png","options":["Sample 20 invoices at the four two-way plants. Three show goods receipts posted after payment.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":3,"prompt":"How would you validate physical receipts and support your conclusion?","anchor":"Material document checks confirm the three late receipts were genuine. This supports a timing problem, not proven fraud. Evidence: THORNFIELD-B24-AP-02-MaterialDoc-CrossCheck.xlsx","options":["Material document checks confirm the three late receipts were genuine. This supports a timing problem, not proven fraud.","Accept management''s explanation without reconciling it to source evidence.","Use only records already reported as successful or approved.","Conclude the control is effective before validating population, timing and exceptions."],"answer":0},{"id":4,"prompt":"How would you review GR/IR aging and support your conclu